import{_ as a,o as l,c as i,O as t}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"Java 基础","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/01-Java基础.md","filePath":"interview/后端/Java/01-Java基础.md","lastUpdated":null}'),o={name:"interview/后端/Java/01-Java基础.md"};function r(n,e,d,c,s,h){return l(),i("div",null,e[0]||(e[0]=[t('<h1 id="java-基础" tabindex="-1">Java 基础 <a class="header-anchor" href="#java-基础" aria-label="Permalink to &quot;Java 基础&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="基本数据类型和包装类区别、integer-缓存机制、自动装箱拆箱-★★★" tabindex="-1">基本数据类型和包装类区别、Integer 缓存机制、自动装箱拆箱 ★★★ <a class="header-anchor" href="#基本数据类型和包装类区别、integer-缓存机制、自动装箱拆箱-★★★" aria-label="Permalink to &quot;基本数据类型和包装类区别、Integer 缓存机制、自动装箱拆箱 ★★★&quot;">​</a></h2><ul><li>8 种基本类型：byte / short / int / long / float / double / char / boolean，对应包装类 Byte、Short、Integer、Long、Float、Double、Character、Boolean。</li><li>区别：包装类是对象（默认值 null、占用堆、可参与泛型），基本类型是值（默认值 0/false、占用栈、性能更好）。</li><li>自动装箱拆箱：编译器调用 <code>Integer.valueOf(int)</code> 装箱、<code>intValue()</code> 拆箱；频繁装箱（如循环中 <code>Integer sum += i</code>）会产生大量临时对象。</li><li>Integer 缓存：<code>valueOf</code> 缓存了 <code>-128 ~ 127</code> 的对象（可 <code>-XX:AutoBoxCacheMax</code> 调整），范围内返回同一对象，之外 new 新对象。故 <code>Integer a=100,b=100; a==b</code> 为 true，<code>128</code> 时为 false。</li></ul><h2 id="面向对象三大特性、抽象类和接口区别-★★★" tabindex="-1">面向对象三大特性、抽象类和接口区别 ★★★ <a class="header-anchor" href="#面向对象三大特性、抽象类和接口区别-★★★" aria-label="Permalink to &quot;面向对象三大特性、抽象类和接口区别 ★★★&quot;">​</a></h2><ul><li>封装：隐藏内部实现，暴露接口（private + getter/setter）。</li><li>继承：子类复用父类成员，单继承、多层继承。</li><li>多态：父类引用指向子类对象，方法调用在运行时动态绑定（重写）；重载是编译期多态。</li></ul><table><thead><tr><th>区别</th><th>抽象类</th><th>接口</th></tr></thead><tbody><tr><td>关键字</td><td>abstract class</td><td>interface</td></tr><tr><td>继承/实现</td><td>单继承</td><td>多实现、接口间多继承</td></tr><tr><td>成员</td><td>可有构造器、普通字段、具体方法</td><td>常量 + 抽象方法；Java8 起可用 default/static 方法，Java9 私有方法</td></tr><tr><td>语义</td><td>is-a，抽取公共</td><td>can-do，定义能力/契约</td></tr></tbody></table><h2 id="string、stringbuilder、stringbuffer-区别-string-不可变原理-常量池-intern-★★★" tabindex="-1">String、StringBuilder、StringBuffer 区别；String 不可变原理；常量池；intern() ★★★ <a class="header-anchor" href="#string、stringbuilder、stringbuffer-区别-string-不可变原理-常量池-intern-★★★" aria-label="Permalink to &quot;String、StringBuilder、StringBuffer 区别；String 不可变原理；常量池；intern() ★★★&quot;">​</a></h2><ul><li>String 不可变：char[]/byte[] 用 <code>final</code> 修饰；所有修改方法都返回新对象。好处：可安全共享、作 HashMap key、线程安全、常量池。</li><li>StringBuilder 非线程安全、StringBuffer 用 synchronized 保证线程安全，均可变。</li><li>常量池：JDK7 起字符串常量池移到堆中，字面量与 <code>intern()</code> 结果放入池。</li><li><code>intern()</code>：若池中已有等值字符串则返回池内引用，否则放入池并返回其引用。</li><li><code>String s = &quot;a&quot; + &quot;b&quot;</code> 编译期常量折叠为 <code>&quot;ab&quot;</code>；含变量的 <code>&quot;a&quot; + b</code> 底层编译为 StringBuilder。</li></ul><h2 id="arraylist-linkedlist-底层实现、扩容机制-★★★" tabindex="-1">ArrayList / LinkedList 底层实现、扩容机制 ★★★ <a class="header-anchor" href="#arraylist-linkedlist-底层实现、扩容机制-★★★" aria-label="Permalink to &quot;ArrayList / LinkedList 底层实现、扩容机制 ★★★&quot;">​</a></h2><ul><li>ArrayList：底层 Object[] 数组，随机访问 O(1)；默认容量 10，每次扩容为 1.5 倍（<code>oldCapacity + oldCapacity &gt;&gt; 1</code>），通过 <code>Arrays.copyOf</code> 复制，产生新数组。</li><li>LinkedList：双向链表，插入删除（已定位节点）O(1)、按索引 O(n)，额外维护前后指针，占用内存更大。</li><li>选择：读多 ArrayList，中段频繁增删 LinkedList（但实际 LinkedList 遍历定位慢，常用 ArrayList 居多）。</li></ul><h2 id="hashmap-底层原理-1-7-和-1-8-区别-红黑树转换条件-扰动函数-扩容机制-★★★" tabindex="-1">HashMap 底层原理，1.7 和 1.8 区别；红黑树转换条件；扰动函数；扩容机制 ★★★ <a class="header-anchor" href="#hashmap-底层原理-1-7-和-1-8-区别-红黑树转换条件-扰动函数-扩容机制-★★★" aria-label="Permalink to &quot;HashMap 底层原理，1.7 和 1.8 区别；红黑树转换条件；扰动函数；扩容机制 ★★★&quot;">​</a></h2><ul><li>结构：JDK1.7 数组 + 链表；JDK1.8 数组 + 链表 + 红黑树。</li><li>扰动函数：<code>(h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)</code>，让高位参与运算，降低碰撞。</li><li>定位：<code>(n-1) &amp; hash</code>，n 为数组长度（2 的幂）。</li><li>红黑树转换：链表长度 ≥ 8（且数组长度 ≥ 64）转红黑树；节点 ≤ 6 时退化为链表（阈值中间 7 留缓冲）。</li><li>扩容：默认容量 16、负载因子 0.75，超过阈值 12 扩容为 2 倍，重新计算索引；JDK1.8 用「高位链表」优化迁移（oldCap 判断新增位，元素要么原位要么原位+oldCap）。</li><li>JDK1.7 扩容采用头插法，并发下可能成环；JDK1.8 改为尾插法修复。</li></ul><h2 id="concurrenthashmap-1-7-和-1-8-实现区别-★★★" tabindex="-1">ConcurrentHashMap 1.7 和 1.8 实现区别 ★★★ <a class="header-anchor" href="#concurrenthashmap-1-7-和-1-8-实现区别-★★★" aria-label="Permalink to &quot;ConcurrentHashMap 1.7 和 1.8 实现区别 ★★★&quot;">​</a></h2><ul><li>1.7：Segment 分段锁，继承 ReentrantLock，每段独立 hash 表，锁粒度是 Segment，并发度 = Segment 数。</li><li>1.8：放弃 Segment，改用「数组 + 链表 + 红黑树」，用 <code>synchronized + CAS</code> 对单个桶加锁；<code>synchronized</code> 锁表头节点，CAS 用于无锁写入（如初始化、binCount 计数）。</li><li>读操作无锁（Node 的 val/next 用 volatile），put 加锁，效率更高。</li></ul><h2 id="hashtable-与-hashmap-对比-★★☆" tabindex="-1">Hashtable 与 HashMap 对比 ★★☆ <a class="header-anchor" href="#hashtable-与-hashmap-对比-★★☆" aria-label="Permalink to &quot;Hashtable 与 HashMap 对比 ★★☆&quot;">​</a></h2><ul><li>Hashtable 线程安全（方法加 synchronized）、不允许 null 键值；HashMap 非线程安全、允许一个 null 键和多个 null 值。</li><li>Hashtable 初始容量 11、扩容 2n+1；HashMap 初始 16、扩容 2 倍。日常用 ConcurrentHashMap 替代 Hashtable。</li></ul><h2 id="异常体系-受检-非受检-try-finally、try-with-resources-★★★" tabindex="-1">异常体系，受检/非受检；try-finally、try-with-resources ★★★ <a class="header-anchor" href="#异常体系-受检-非受检-try-finally、try-with-resources-★★★" aria-label="Permalink to &quot;异常体系，受检/非受检；try-finally、try-with-resources ★★★&quot;">​</a></h2><ul><li>根 <code>Throwable</code> → <code>Error</code>（不可恢复，如 OOM、StackOverflow）和 <code>Exception</code>。</li><li><code>Exception</code> 分受检（编译期强制处理，IOException/SQLException）和非受检（RuntimeException 及其子类，NPE、IndexOutOfBounds）。</li><li>finally 总执行（除非 System.exit）；return 在 finally 中会覆盖 try 的 return 值。</li><li>try-with-resources：实现 AutoCloseable 的资源自动关闭，避免 finally 里重复关闭。</li></ul><h2 id="泛型原理-泛型擦除-、-extends、-super-★★★" tabindex="-1">泛型原理，泛型擦除；?、? extends、? super ★★★ <a class="header-anchor" href="#泛型原理-泛型擦除-、-extends、-super-★★★" aria-label="Permalink to &quot;泛型原理，泛型擦除；?、? extends、? super ★★★&quot;">​</a></h2><ul><li>泛型擦除：编译期擦除类型参数，替换为上限或 Object，插入转型；运行时无泛型信息（<code>List&lt;String&gt;</code> 与 <code>List&lt;Integer&gt;</code> 同一 class）。</li><li><code>?</code> 无限制通配符；<code>? extends T</code> 上界（只能读、不能写 add，除了 null）；<code>? super T</code> 下界（可写 T，读为 Object）。</li><li>记住 PECS：Producer Extends，Consumer Super。</li></ul><h2 id="反射机制-获取-class-对象的几种方式-反射优缺点-★★★" tabindex="-1">反射机制，获取 Class 对象的几种方式，反射优缺点 ★★★ <a class="header-anchor" href="#反射机制-获取-class-对象的几种方式-反射优缺点-★★★" aria-label="Permalink to &quot;反射机制，获取 Class 对象的几种方式，反射优缺点 ★★★&quot;">​</a></h2><ul><li>获取：<code>类名.class</code>、<code>obj.getClass()</code>、<code>Class.forName(&quot;全限定名&quot;)</code>（触发初始化）、类加载器 loadClass（不初始化）。</li><li>用途：动态创建对象（newInstance）、获取/调用构造器、字段、方法，用于框架（Spring、MyBatis）。</li><li>优点：动态、灵活；缺点：绕开编译检查、性能较低（可缓存 Method/Field 缓解）、破坏封装。</li></ul><h2 id="注解-元注解-自定义注解-★★☆" tabindex="-1">注解，元注解，自定义注解 ★★☆ <a class="header-anchor" href="#注解-元注解-自定义注解-★★☆" aria-label="Permalink to &quot;注解，元注解，自定义注解 ★★☆&quot;">​</a></h2><ul><li>元注解：@Target（作用域）、@Retention（保留级别 SOURCE/CLASS/RUNTIME）、@Documented、@Inherited。</li><li>自定义：<code>@interface</code> 声明，属性形如 <code>String value() default &quot;&quot;</code>。</li><li>解析：运行期反射读取（getAnnotation），编译期通过注解处理器（APT）。</li></ul><h2 id="bio-nio-aio-区别-buffer、channel-★★★" tabindex="-1">BIO / NIO / AIO 区别；Buffer、Channel ★★★ <a class="header-anchor" href="#bio-nio-aio-区别-buffer、channel-★★★" aria-label="Permalink to &quot;BIO / NIO / AIO 区别；Buffer、Channel ★★★&quot;">​</a></h2><ul><li>BIO：同步阻塞，一连接一线程；NIO：同步非阻塞，Selector 多路复用（一个线程管理多连接）；AIO：异步非阻塞，回调。</li><li>Buffer 缓冲区（容量 capacity、位置 position、上限 limit）；Channel 双向通道（FileChannel、SocketChannel、ServerSocketChannel）；Selector 注册 channel 监听就绪事件。</li></ul><h2 id="与-equals、hashcode-契约-★★★" tabindex="-1">== 与 equals、hashCode 契约 ★★★ <a class="header-anchor" href="#与-equals、hashcode-契约-★★★" aria-label="Permalink to &quot;== 与 equals、hashCode 契约 ★★★&quot;">​</a></h2><ul><li><code>==</code> 比较基本类型的值或引用地址；<code>equals</code> 默认也是引用比较，String/Integer 重写为值比较。</li><li>重写 equals 必须重写 hashCode：相等对象 hashCode 必须相等；反之 hashCode 相等不代表 equals 相等。否则放入 HashSet/HashMap 会出问题。</li></ul><h2 id="深拷贝与浅拷贝、序列化-serialversionuid-★★☆" tabindex="-1">深拷贝与浅拷贝、序列化 serialVersionUID ★★☆ <a class="header-anchor" href="#深拷贝与浅拷贝、序列化-serialversionuid-★★☆" aria-label="Permalink to &quot;深拷贝与浅拷贝、序列化 serialVersionUID ★★☆&quot;">​</a></h2><ul><li>浅拷贝：只复制引用，对象内引用类型共享；深拷贝：完全独立副本。</li><li>实现：实现 Cloneable + 覆写 clone（浅）；深拷贝需递归 clone 或序列化反序列化。</li><li>serialVersionUID：序列化版本号，缺省时 JVM 根据类结构自动生成，类改动会导致反序列化 InvalidClassException；显式声明避免。</li></ul><h2 id="bigdecimal-与浮点精度-★★★" tabindex="-1">BigDecimal 与浮点精度 ★★★ <a class="header-anchor" href="#bigdecimal-与浮点精度-★★★" aria-label="Permalink to &quot;BigDecimal 与浮点精度 ★★★&quot;">​</a></h2><ul><li>float/double 二进制无法精确表示十进制小数（0.1），运算出现误差；金额计算用 BigDecimal。</li><li>BigDecimal 用字符串构造 <code>new BigDecimal(&quot;0.1&quot;)</code>，避免 <code>new BigDecimal(0.1)</code>；运算用 add/subtract/multiply/divide（divide 指定 RoundingMode）。</li></ul><h2 id="四种内部类-★☆☆" tabindex="-1">四种内部类 ★☆☆ <a class="header-anchor" href="#四种内部类-★☆☆" aria-label="Permalink to &quot;四种内部类 ★☆☆&quot;">​</a></h2><ul><li>成员内部类（可访问外部类成员）、静态内部类（不依赖外部实例）、局部内部类（方法内）、匿名内部类（一次性实现，如 new Runnable(){}，只能访问 final/effectively final 变量）。</li></ul><h2 id="枚举原理-★★☆" tabindex="-1">枚举原理 ★★☆ <a class="header-anchor" href="#枚举原理-★★☆" aria-label="Permalink to &quot;枚举原理 ★★☆&quot;">​</a></h2><ul><li>enum 本质是继承 java.lang.Enum 的 final 类，每个常量是 public static final 实例；构造器私有；可定义字段、方法、实现接口；线程安全单例的常用实现方式之一。</li></ul><h2 id="函数式接口、lambda、stream-★★★" tabindex="-1">函数式接口、Lambda、Stream ★★★ <a class="header-anchor" href="#函数式接口、lambda、stream-★★★" aria-label="Permalink to &quot;函数式接口、Lambda、Stream ★★★&quot;">​</a></h2><ul><li>函数式接口：仅一个抽象方法（@FunctionalInterface），如 Function、Predicate、Consumer、Supplier。</li><li>Lambda：函数式接口的简洁实现；Stream：中间操作（filter/map/sorted）惰性、终结操作（collect/forEach/reduce）触发。</li></ul><h2 id="值传递与引用传递-前端转全栈必考-★★★" tabindex="-1">值传递与引用传递（前端转全栈必考）★★★ <a class="header-anchor" href="#值传递与引用传递-前端转全栈必考-★★★" aria-label="Permalink to &quot;值传递与引用传递（前端转全栈必考）★★★&quot;">​</a></h2><ul><li>Java 中只有「值传递」，没有引用传递： <ul><li>基本类型：传的是「值的副本」，方法内改参数不影响外部变量。</li><li>引用类型：传的是「引用（地址）的副本」，副本和原引用指向同一个对象，所以方法内修改「对象内容」会影响外部；但修改「引用本身」（重新 new 或指向别的对象）不会影响外部引用。</li></ul></li><li>常考例子：写一个 <code>swap(a, b)</code> 交换两个对象，方法外不会真正交换，因为改的是副本引用。</li><li>与 JS 对比：JS 对 primitive 也是按值、对 object 是传「引用副本」，行为一致；关键差别是 Java 强调「只有值传递」这个结论，面试常让人辨析。</li></ul><h2 id="final、finally、finalize-区别-★★★" tabindex="-1">final、finally、finalize 区别 ★★★ <a class="header-anchor" href="#final、finally、finalize-区别-★★★" aria-label="Permalink to &quot;final、finally、finalize 区别 ★★★&quot;">​</a></h2><ul><li>final：修饰类（不能被继承）、方法（不能被重写）、变量（基本类型值不可变；引用类型引用不可变，但指向的对象内容可变）。</li><li>finally：异常处理关键字，无论是否抛异常都执行（除非 System.exit / 线程被 kill）；常考 finally 中的 return 会覆盖 try 里的 return。</li><li>finalize：Object 的方法，对象被 GC 回收前调用；JDK9 起已废弃（执行时机不确定、性能差、可能复活对象），不建议用。</li></ul><h2 id="object-类常用方法-★★☆" tabindex="-1">Object 类常用方法 ★★☆ <a class="header-anchor" href="#object-类常用方法-★★☆" aria-label="Permalink to &quot;Object 类常用方法 ★★☆&quot;">​</a></h2><ul><li>equals、hashCode、toString、clone、getClass、finalize、wait/notify/notifyAll。</li><li>equals/hashCode 要成对重写（见上文契约）；toString 建议重写便于日志排查；clone 需实现 Cloneable。</li></ul><h2 id="类初始化顺序、静态变量-代码块-★★☆" tabindex="-1">类初始化顺序、静态变量/代码块 ★★☆ <a class="header-anchor" href="#类初始化顺序、静态变量-代码块-★★☆" aria-label="Permalink to &quot;类初始化顺序、静态变量/代码块 ★★☆&quot;">​</a></h2><ul><li>加载顺序：父类静态变量/静态代码块 → 子类静态变量/静态代码块 → 父类实例变量/代码块/构造器 → 子类实例变量/代码块/构造器。</li><li>静态变量和静态块只在类加载（首次使用）时执行一次；实例代码块每次 new 都执行，且在构造器之前。</li><li>同类内部：静态变量/静态块按书写顺序，实例变量/实例块按书写顺序，最后构造器。</li></ul><h2 id="comparable-与-comparator-区别-★★☆" tabindex="-1">Comparable 与 Comparator 区别 ★★☆ <a class="header-anchor" href="#comparable-与-comparator-区别-★★☆" aria-label="Permalink to &quot;Comparable 与 Comparator 区别 ★★☆&quot;">​</a></h2><ul><li>Comparable（内部比较器）：类实现 <code>compareTo(o)</code>，定义「自然排序」，与自身比较，侵入类内部。</li><li>Comparator（外部比较器）：实现 <code>compare(a, b)</code>，可在不修改类的前提下定义多种排序规则；常配合 lambda <code>Comparator.comparing(...)</code>。</li><li>用法：<code>Collections.sort(list, comparator)</code>、<code>stream().sorted(comparator)</code>；TreeSet/TreeMap 也依赖它们。</li></ul><h2 id="java-8-新特性汇总、optional-★★★" tabindex="-1">Java 8 新特性汇总、Optional ★★★ <a class="header-anchor" href="#java-8-新特性汇总、optional-★★★" aria-label="Permalink to &quot;Java 8 新特性汇总、Optional ★★★&quot;">​</a></h2><ul><li>新特性：Lambda、函数式接口、方法引用（<code>::</code>）、Stream、Optional、新时间日期 API（LocalDate/LocalDateTime/Instant/DateTimeFormatter）、接口 default/static 方法、CompletableFuture、Base64、可重复注解。</li><li>前端转 Java 重点掌握：Lambda + Stream + Optional，三者是最常用的现代 Java 写法。</li></ul><h3 id="optional-★★★" tabindex="-1">Optional ★★★ <a class="header-anchor" href="#optional-★★★" aria-label="Permalink to &quot;Optional ★★★&quot;">​</a></h3><ul><li>用途：包装可能为 null 的值，显式表达「可能为空」，避免 NPE。</li><li>常用：<code>of</code> / <code>ofNullable</code> / <code>empty</code> 创建；<code>isPresent</code> / <code>ifPresent</code> 判断执行；<code>orElse</code> / <code>orElseGet</code> / <code>orElseThrow</code> 兜底；<code>map</code> / <code>flatMap</code> 转换。</li><li>注意：<code>orElse</code> 无论值是否存在都会计算参数，<code>orElseGet</code> 惰性求值；Optional 建议只作方法返回值，不要作字段或方法参数。</li></ul><h2 id="集合框架选型总结-★★★" tabindex="-1">集合框架选型总结 ★★★ <a class="header-anchor" href="#集合框架选型总结-★★★" aria-label="Permalink to &quot;集合框架选型总结 ★★★&quot;">​</a></h2><ul><li>List：需要有序、可重复 → 读多 ArrayList，频繁首尾插入或做队列/栈 LinkedList。</li><li>Set：去重 → HashSet（无序、O(1)）、LinkedHashSet（保持插入顺序）、TreeSet（按元素自然序/比较器排序）。</li><li>Map：HashMap（无序）、LinkedHashMap（保持插入顺序，可做 LRU）、TreeMap（按 key 排序）、ConcurrentHashMap（并发）。</li><li>线程安全：并发容器 ConcurrentHashMap、CopyOnWriteArrayList；或 <code>Collections.synchronizedXxx</code> 包装。</li></ul>',55)]))}const f=a(o,[["render",r]]);export{b as __pageData,f as default};
